let projects=[],current=null,selected=null,template='default',filter='All',templateFilter='All',page=0,list=false,opened=false,savedClass='',sketch=[],playing=false,startState=null,world=null,bodies=new Map(),elapsed=0,keys=new Set(),activeXR=null;
