function categories(container,active,callback){container.replaceChildren();for(const name of M.categories){const b=document.createElement('button');b.textContent=name;b.className='xr-pill';b.setAttribute('aria-pressed',String(name===active));b.onclick=()=>callback(name);container.append(b);}}
function show(section){root.classList.toggle('xr-editing',section==='editor');if(section!=='editor')stopPython();for(const id of ['dashboard','wizard','editor'])$('xr-'+id).hidden=id!==section;if(section!=='editor')stop();if(section==='editor')requestAnimationFrame(resize);}
function store(){try{localStorage.setItem(KEY,JSON.stringify(projects));return true;}catch{status('Browser storage is full. Export this project to keep a copy.');return false;}}
function save(){if(!current)return false;const previousProjects=M.clone(projects);stop();syncActiveScene();if(renderer&&scene&&camera){renderer.render(scene,camera);current.preview=renderer.domElement.toDataURL('image/jpeg',.55);}const existing=projects.find(p=>p.id===current.id);if(existing){const history=backups.get(current.id)||[];history.unshift(M.clone(existing));backups.set(current.id,history.slice(0,5));try{localStorage.setItem('block-studio.xr.backups.'+current.id,JSON.stringify(history.slice(0,5)));}catch{}}current.updated=Date.now();const copy=M.validate(current),index=projects.findIndex(p=>p.id===copy.id);if(index<0)projects.unshift(copy);else projects[index]=copy;if(!store()){projects=previousProjects;return false;}const historySaved=persistUndo(copy);status(historySaved?'Project and Undo history saved in this browser.':'Project saved; Undo history could not fit in browser storage.');renderBackups();return true;}
async function confirmLeave(){stop();if(!current||$('xr-editor').hidden)return true;const saved=projects.find(p=>p.id===current.id);if(saved&&JSON.stringify(saved)===JSON.stringify(current))return true;const result=await StudioPython.ask('Unsaved scene','Save your scene changes before leaving?',undefined,['Save and leave','Leave without saving']);if(result==='Save and leave')return save();return result==='Leave without saving';}
function renderProjects(){categories($('xr-filters'),filter,name=>{filter=name;page=0;renderProjects();});const q=$('xr-search').value.toLowerCase(),items=projects.filter(p=>(filter==='All'||p.category===filter)&&p.name.toLowerCase().includes(q)).sort((a,b)=>b.updated-a.updated);page=Math.min(page,Math.max(0,Math.ceil(items.length/12)-1));const visible=items.slice(page*12,page*12+12);$('xr-count').textContent=(items.length?page*12+1:0)+'–'+(page*12+visible.length)+' of '+items.length;$('xr-prev').disabled=page===0;$('xr-next').disabled=(page+1)*12>=items.length;$('xr-projects').replaceChildren();$('xr-projects').classList.toggle('is-list',list);$('xr-empty').hidden=items.length>0;$('xr-empty-message').textContent=projects.length?'No projects match your search.':'Your 3D projects will appear here.';for(const p of visible){const card=document.createElement('article');card.className='xr-project-card';const open=document.createElement('button');open.className='xr-project-open';const image=document.createElement('div');image.className='xr-card-preview';if(p.preview){const img=new Image();img.src=p.preview;img.alt='';image.append(img);}else image.textContent=p.category==='Physics'?'◉':p.category==='Game'?'▰':'⬡';const title=document.createElement('strong');title.textContent=p.name;const desc=document.createElement('span');desc.textContent=p.description||p.category;open.append(image,title,desc);open.onclick=()=>edit(M.clone(p));const actions=document.createElement('div');for(const [label,fn]of [['Rename',async()=>{const name=await StudioPython.ask('Rename project','Enter a project name.',p.name,['Save name']);if(name?.trim()){p.name=name.trim().slice(0,120);store();renderProjects();}}],['Export',()=>download(p.name+'.xr.json',JSON.stringify(p,null,2))],['Delete',async()=>{if(await StudioPython.ask('Delete XR project','Remove '+p.name+' from this browser? Export a copy first.',undefined,['Delete project'])){projects=projects.filter(x=>x.id!==p.id);store();renderProjects();}}]]){const b=document.createElement('button');b.textContent=label;b.onclick=fn;actions.append(b);}card.append(open,actions);$('xr-projects').append(card);}}
function templateThumbnail(type){const sky=type==='solar'?'#252345':type==='city'?'#cbeaf4':'#e6dfed',cube='<path d="M82 83 121 62l39 21-39 23Z" fill="#c698da"/><path d="M82 83v45l39 23v-45Z" fill="#9d6aba"/><path d="M121 106l39-23v45l-39 23Z" fill="#77498c"/>',bear='<g fill="#ba8dcb" stroke="#8a60a0" stroke-width="2"><ellipse cx="120" cy="117" rx="25" ry="35"/><circle cx="100" cy="51" r="10"/><circle cx="140" cy="51" r="10"/><circle cx="120" cy="73" r="29"/><rect x="97" y="63" width="46" height="17" rx="5" fill="#8ee0e9"/><ellipse cx="104" cy="153" rx="9" ry="16"/><ellipse cx="136" cy="153" rx="9" ry="16"/></g>';let art=type==='default'||type==='animation'?bear:type==='physics'?'<circle cx="95" cy="62" r="25" fill="#f7b846"/>'+cube:type==='solar'?'<circle cx="120" cy="95" r="35" fill="#ffcf57"/><ellipse cx="120" cy="95" rx="90" ry="45" fill="none" stroke="#aba5d5"/><circle cx="207" cy="85" r="13" fill="#64b6e3"/>':type==='car'?'<rect x="65" y="95" width="115" height="45" rx="12" fill="#f6b343"/><path d="M90 95 108 67h45l20 28Z" fill="#86d2df"/><circle cx="90" cy="142" r="16" fill="#474052"/><circle cx="158" cy="142" r="16" fill="#474052"/>':type==='city'?cube+'<path d="M69 84 121 40l52 44Z" fill="#d17a79"/><rect x="111" y="121" width="20" height="30" fill="#f4d179"/>':type==='maze'?'<path d="M45 40h150v115H45ZM80 40v80h45V80h70M45 150h115v-35" fill="none" stroke="#9671ae" stroke-width="13"/><circle cx="61" cy="137" r="10" fill="#ffbc49"/>':'<circle cx="120" cy="90" r="40" fill="none" stroke="#a7a0b1" stroke-width="7"/><path d="M55 150h130" stroke="#a7a0b1" stroke-width="7"/>';return '<svg viewBox="0 0 240 180" aria-hidden="true"><rect width="240" height="180" fill="'+sky+'"/>'+(type==='solar'?'':'<path d="M0 130 120 80l120 50v50H0Z" fill="#ffffff55"/><path d="M0 160h240M60 120v60M120 100v80M180 120v60" stroke="#b8b0c833"/>')+art+'</svg>';}
function renderTemplates(){categories($('xr-template-filters'),templateFilter,c=>{templateFilter=c;renderTemplates();});$('xr-templates').replaceChildren();for(const [id,name,category,description,icon]of templates){if(templateFilter!=='All'&&category!==templateFilter)continue;const b=document.createElement('button');b.type='button';b.className='xr-template';b.setAttribute('aria-pressed',String(template===id));b.disabled=['face','hand'].includes(id);const preview=document.createElement('div');preview.className='xr-template-preview';preview.innerHTML=templateThumbnail(id);const label=document.createElement('strong');label.textContent=name;const desc=document.createElement('span');desc.textContent=description;b.append(preview,label,desc);b.onclick=()=>{template=id;renderTemplates();};$('xr-templates').append(b);}}
