function initRenderer(){if(renderer)return true;try{renderer=new THREE.WebGLRenderer({antialias:true,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.shadowMap.enabled=true;renderer.xr.enabled=true;scene=new THREE.Scene();camera=new THREE.PerspectiveCamera(50,1,.05,20000);camera.position.set(9,7,11);mainCamera=camera;arCamera=camera.clone();arCamera.position.set(5,4,8);arCamera.lookAt(0,1,0);arCameraHelper=new THREE.CameraHelper(arCamera);mainCameraHelper=new THREE.CameraHelper(mainCamera);scene.add(arCameraHelper,mainCameraHelper);axesHelper=new THREE.AxesHelper(2);scene.add(axesHelper);orbit=new OrbitControls(camera,renderer.domElement);orbit.target.set(0,1,0);orbit.enableDamping=true;orbit.minDistance=.1;orbit.maxDistance=5000;orbit.maxPolarAngle=Math.PI/2-.01;transform=new TransformControls(camera,renderer.domElement);scene.add(transform.getHelper());transform.addEventListener('dragging-changed',e=>{orbit.enabled=!e.value;if(e.value)remember();else syncFromMesh();});transform.addEventListener('objectChange',()=>{if(selected)updateVectorFields();});hemisphereLight=new THREE.HemisphereLight(0xffffff,0x9992a8,2.5);scene.add(hemisphereLight);const sun=new THREE.DirectionalLight(0xffffff,3);directionalLight=sun;sun.position.set(6,12,8);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);scene.add(sun);grid=new THREE.GridHelper(40,40,0xaaa2b2,0xd4cfdb);grid.position.y=.012;scene.add(grid);ground=new THREE.Mesh(new THREE.PlaneGeometry(100,100),new THREE.MeshStandardMaterial({color:0xffffff,roughness:1,side:THREE.DoubleSide}));ground.rotation.x=-Math.PI/2;ground.receiveShadow=true;scene.add(ground);selectionBox=new THREE.BoxHelper(new THREE.Mesh(),0xf5ba34);selectionBox.visible=false;scene.add(selectionBox);$('xr-stage').prepend(renderer.domElement);renderer.domElement.setAttribute('aria-label','3D scene viewport');renderer.domElement.tabIndex=0;let pointerStart;renderer.domElement.addEventListener('pointerdown',e=>pointerStart=[e.clientX,e.clientY]);renderer.domElement.addEventListener('pointerup',e=>{if(playing||transform.dragging||!pointerStart||Math.hypot(e.clientX-pointerStart[0],e.clientY-pointerStart[1])>4)return;const r=renderer.domElement.getBoundingClientRect();raycaster.setFromCamera(new THREE.Vector2((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1),camera);const hits=raycaster.intersectObjects([...meshes.values()],true);const hit=hits.find(h=>h.object.visible);let obj=hit?.object;while(obj&&!obj.userData.xrId)obj=obj.parent;select(obj?.userData.xrId||null);});renderer.setAnimationLoop(tick);new ResizeObserver(resize).observe($('xr-stage'));checkXR();return true;}catch(error){$('xr-render-error').hidden=false;$('xr-render-error').textContent='3D rendering could not start: '+error.message;status('WebGL2 is required for the 3D viewport.');return false;}}
