function dispose(o){o.traverse(m=>{m.geometry?.dispose();for(const mat of Array.isArray(m.material)?m.material:[m.material]){mat?.map?.dispose();mat?.dispose();}});}
let isolatedView=false;
function applyIsolation(){if(!current)return;if(!selectedObject())isolatedView=false;for(const o of current.objects){const mesh=meshes.get(o.id);if(mesh)mesh.visible=o.visible&&(!isolatedView||o.id===selected);}const b=$('xr-isolate');if(b){b.textContent=isolatedView?'Show all objects':'Isolate selected';b.setAttribute('aria-pressed',String(isolatedView));}}
function rebuild(){if(!scene)return;for(const media of mediaElements.values()){media.pause();media.removeAttribute('src');media.load();}mediaElements.clear();$('xr-media-preview')?.replaceChildren();transform.detach();for(const m of meshes.values()){scene.remove(m);dispose(m);}meshes.clear();for(const o of current.objects){const mesh=build(o);scene.add(mesh);meshes.set(o.id,mesh);}applySceneEnvironment();select(selected);renderLayers();}
function resize(){if(!renderer||$('xr-editor').hidden)return;const r=$('xr-stage').getBoundingClientRect();if(!r.width||!r.height)return;renderer.setSize(r.width,r.height);for(const c of [mainCamera,arCamera]){c.aspect=r.width/r.height;c.updateProjectionMatrix();}}
function selectedObject(){return current?.objects.find(o=>o.id===selected);}
function select(id){document.querySelector('.xr-inspector')?.classList.remove('xr-listener-visible');selectedPart=null;document.querySelector('.xr-inspector')?.classList.remove('xr-part-visible');if(id)showEditorSettings(false);const selectionChanged=id!==selected;selected=id;if(selectionChanged)document.querySelector('.xr-inspector').scrollTop=0;const o=selectedObject(),mesh=meshes.get(id);transform?.detach();if(selectionBox)selectionBox.visible=!!mesh&&!playing;if(mesh&&transform&&!playing){transform.attach(mesh);selectionBox.setFromObject(mesh);}renderInspector();renderLayers();renderActions();renderModeling();applyIsolation();}
const historySelections=new WeakMap();
function captureHistory(){const snapshot=M.clone(current);historySelections.set(snapshot,{id:selected,target:$('xr-model-target').value,part:selectedPart?{...selectedPart}:null});return snapshot;}
function restoreHistory(snapshot){current=snapshot;const selection=historySelections.get(snapshot);selected=current.objects.some(o=>o.id===selection?.id)?selection.id:null;$('xr-project-name').value=current.name;changed();if(selection?.target&&Array.from($('xr-model-target').options).some(o=>o.value===selection.target)){$('xr-model-target').value=selection.target;updateModelingAvailability();}if(selection?.part&&selected)choosePart(selected,selection.part.path);}
function remember(){if(playing)stop();past.push(captureHistory());if(past.length>40)past.shift();future=[];syncHistory();}
function persistUndo(project){try{localStorage.setItem('block-studio.xr.undo.'+project.id,encodeHistory(project,past,future,p=>historySelections.get(p)));return true;}catch{return false;}}
function loadUndo(){let raw;try{raw=localStorage.getItem('block-studio.xr.undo.'+current.id);}catch{return;}const data=decodeHistory(raw,current,M.validate);if(!data)return;past=data.past.map(e=>e.project);future=data.future.map(e=>e.project);for(const entry of [...data.past,...data.future])if(entry.selection)historySelections.set(entry.project,entry.selection);}
function syncHistory(){$('xr-undo').disabled=!past.length;$('xr-redo').disabled=!future.length;}
function changed(){selectedPart=null;document.querySelector('.xr-inspector')?.classList.remove('xr-part-visible');rebuild();renderSceneList();syncHistory();if(document.querySelector('.xr-inspector').classList.contains('xr-settings-visible'))showEditorSettings(true);status('Scene updated. Choose Save to keep your project.');}
function addObject(type,extra={}){if(current.objects.length>=200)return status('Scene limit reached: 200 objects.');remember();const o=M.object(type,extra),base=o.name;let suffix=2;while(current.objects.some(item=>item.name===o.name))o.name=base+' '+suffix++;current.objects.push(o);selected=o.id;changed();}
function edit(p){isolatedView=false;stopPython();current=M.validate(p);selected=null;past=[];future=[];loadUndo();ensureScenes();show('editor');$('xr-project-name').value=current.name;$('xr-python-source').value=current.pythonSource||'obj = XRObject("Scout Bear")\nobj.set_position(0, 0, 0)\nobj.set_color("#a466b3")\nprint("Scene updated")';initRenderer();rebuild();applySceneEnvironment(true);renderSceneList();showEditorSettings(true);$('xr-library-panel').hidden=true;renderInspector();renderBackups();syncHistory();status('Scene ready. Select a layer or add an object.');}
function renderLayers(){renderHierarchy();}
for(const key of ['position','rotation','scale']){const label=document.createElement('label');label.textContent=key[0].toUpperCase()+key.slice(1);const row=document.createElement('div');row.className='xr-vector';for(const [i,axis]of ['X','Y','Z'].entries()){const input=document.createElement('input');input.type='number';input.step=key==='rotation'?'5':'.1';input.setAttribute('aria-label',key+' '+axis);input.dataset.vector=key;input.dataset.axis=i;input.onchange=()=>{const o=selectedObject();if(!o)return;const n=Number(input.value);if(!Number.isFinite(n)||Math.abs(n)>1000||(key==='scale'&&(n<=0||n>100)))return renderInspector();remember();o[key][i]=n;changed();};row.append(input);}label.append(row);$('xr-vectors').append(label);}
function updateVectorFields(){const mesh=selectedPart?partMesh():meshes.get(selected);if(!mesh)return;root.querySelectorAll('[data-vector]').forEach(input=>{const values=input.dataset.vector==='position'?mesh.position.toArray():input.dataset.vector==='rotation'?[mesh.rotation.x,mesh.rotation.y,mesh.rotation.z].map(THREE.MathUtils.radToDeg):mesh.scale.toArray().map((v,i)=>!selectedPart&&selectedObject()?.type==='text'&&i===0?v/4:v);input.value=Number(values[Number(input.dataset.axis)].toFixed(3));});selectionBox?.setFromObject(mesh);}
