function renderInspector(){const o=selectedObject();$('xr-properties').disabled=!o||playing;$('xr-no-selection').hidden=!!o;for(const id of ['xr-delete','xr-duplicate','xr-ground'])$(id).disabled=!o||playing;if(o){$('xr-object-name').value=o.name;$('xr-visible').checked=o.visible;$('xr-color').value=o.color;$('xr-material').value=o.material;$('xr-physics').checked=o.physics;$('xr-mass').value=o.mass;$('xr-bounce').value=o.bounce;$('xr-spin').value=o.animation?.spin||0;$('xr-bob').value=o.animation?.bob||0;updateVectorFields();}if(current){$('xr-background').value=current.environment.background;$('xr-gravity').value=current.environment.gravity;$('xr-show-grid').checked=current.environment.grid;}}
function setProperty(id,fn){$(id).onchange=()=>{const o=selectedObject();if(!o)return;remember();fn(o,$(id));changed();};}
setProperty('xr-object-name',(o,e)=>o.name=e.value.trim().slice(0,120)||o.type);setProperty('xr-visible',(o,e)=>o.visible=e.checked);setProperty('xr-color',(o,e)=>o.color=e.value);setProperty('xr-material',(o,e)=>o.material=e.value);setProperty('xr-physics',(o,e)=>o.physics=e.checked);setProperty('xr-mass',(o,e)=>o.mass=Math.max(0,Math.min(1000,Number(e.value)||0)));setProperty('xr-bounce',(o,e)=>o.bounce=Math.max(0,Math.min(1,Number(e.value)||0)));setProperty('xr-spin',(o,e)=>o.animation.spin=Math.max(-360,Math.min(360,Number(e.value)||0)));setProperty('xr-bob',(o,e)=>o.animation.bob=Math.max(0,Math.min(10,Number(e.value)||0)));
$('xr-apply-properties').onclick=()=>{const o=selectedObject();if(!o)return;const vectors={};for(const key of ['position','rotation','scale']){vectors[key]=Array.from(root.querySelectorAll('[data-vector="'+key+'"]')).map(input=>Number(input.value));if(vectors[key].some(v=>!Number.isFinite(v)||Math.abs(v)>1000||(key==='scale'&&(v<=0||v>100))))return status('Enter finite transforms; scale must be between 0.01 and 100.');}remember();Object.assign(o,vectors,{name:$('xr-object-name').value.trim().slice(0,120)||o.type,visible:$('xr-visible').checked,color:$('xr-color').value,material:$('xr-material').value,physics:$('xr-physics').checked,mass:Math.max(0,Math.min(1000,Number($('xr-mass').value)||0)),bounce:Math.max(0,Math.min(1,Number($('xr-bounce').value)||0)),animation:{...o.animation,spin:Math.max(-360,Math.min(360,Number($('xr-spin').value)||0)),bob:Math.max(0,Math.min(10,Number($('xr-bob').value)||0))}});changed();};
for(const [id,key]of [['xr-background','background'],['xr-gravity','gravity'],['xr-show-grid','grid']])$(id).onchange=()=>{remember();current.environment[key]=key==='grid'?$(id).checked:key==='gravity'?Math.max(-50,Math.min(50,Number($(id).value)||0)):$(id).value;if(key==='gravity')current.environment.gravityVector[1]=current.environment.gravity;changed();};
for(const type of ['box','sphere','cylinder','cone','plane','torus','bear','robot','house','tree','car','text','light']){const b=document.createElement('button');b.textContent=type[0].toUpperCase()+type.slice(1);b.onclick=async()=>{if(type==='text'){const text=await StudioPython.ask('3D text','Enter a label.','Hello 3D',['Add text']);if(text)addObject('text',{text:text.slice(0,500)});}else addObject(type,{position:['bear','robot','house','tree'].includes(type)?[0,0,0]:[0,1,0]});};$('xr-library').append(b);}
function renderModeling(){renderJointTree();renderToolAvailability();const select=$('xr-model-target'),previous=select.value;select.replaceChildren();for(const o of current?.objects||[]){if(o.id===selected)continue;const option=document.createElement('option');option.value=o.id;option.textContent=o.name;select.append(option);}if(Array.from(select.options).some(o=>o.value===previous))select.value=previous;$('xr-joints').replaceChildren();for(const [i,j]of (current?.joints||[]).entries()){const button=document.createElement('button');button.textContent=j.type+' joint ×';button.title='Remove joint';button.onclick=()=>{remember();current.joints.splice(i,1);renderModeling();};$('xr-joints').append(button);}updateModelingAvailability();}
function booleanOperation(operation){const a=selectedObject(),b=current.objects.find(o=>o.id===$('xr-model-target').value),meshA=solidForBoolean(meshes.get(a?.id)),meshB=solidForBoolean(meshes.get(b?.id));if(!meshA?.isMesh||!meshB?.isMesh)return status('Select two solid mesh objects, such as a Box and Sphere.');try{meshA.updateMatrix();meshB.updateMatrix();const result=CSG[operation](meshA,meshB),geometry=result.geometry.clone().applyMatrix4(result.matrix),positions=geometry.attributes.position,normals=geometry.attributes.normal;if(!positions?.count)return status('The operation produced an empty solid. Move the objects to overlap.');let source='';for(let i=0;i<positions.count;i++)source+='v '+positions.getX(i)+' '+positions.getY(i)+' '+positions.getZ(i)+'\n';if(normals)for(let i=0;i<normals.count;i++)source+='vn '+normals.getX(i)+' '+normals.getY(i)+' '+normals.getZ(i)+'\n';for(let i=0;i<positions.count;i+=3)source+='f '+[i+1,i+2,i+3].map(n=>normals?n+'//'+n:n).join(' ')+'\n';geometry.dispose();result.geometry.dispose();if(source.length>3000000)return status('Boolean result is too large. Use simpler meshes.');remember();current.objects=current.objects.filter(o=>o.id!==a.id&&o.id!==b.id);current.joints=(current.joints||[]).filter(j=>![a.id,b.id].includes(j.a)&&![a.id,b.id].includes(j.b));const o=M.object('obj',{name:operation+' result',source,position:[0,0,0],color:a.color});current.objects.push(o);selected=o.id;changed();}catch(e){status('Modeling operation failed: '+e.message);}finally{for(const mesh of [meshA,meshB])if(mesh?.userData.temporaryBoolean){mesh.geometry.dispose();mesh.material.dispose();}}}
for(const kind of ['union','subtract','intersect'])$('xr-'+kind).onclick=()=>booleanOperation(kind);
for(const [i,axis]of ['x','y','z'].entries())$('xr-align-'+axis).onclick=()=>{const a=selectedObject(),b=current.objects.find(o=>o.id===$('xr-model-target').value);if(!a||!b)return status('Select two objects to align.');remember();a.position[i]=b.position[i];changed();};
for(const type of ['fixed','hinge'])$('xr-joint-'+type).onclick=()=>{const a=selectedObject(),b=current.objects.find(o=>o.id===$('xr-model-target').value);if(!a||!b)return status('Select two objects for the joint.');if((current.joints||[]).some(j=>j.a===a.id&&j.b===b.id))return status('These objects already have a joint.');remember();a.physics=b.physics=true;current.joints=current.joints||[];current.joints.push({a:a.id,b:b.id,type});changed();status('Joint added. Play previews the physics connection.');};
function renderActions(){$('xr-actions').replaceChildren();const o=selectedObject();for(const [index,a]of (o?.actions||[]).entries()){const b=document.createElement('button');b.textContent=a.kind+' '+a.axis+' '+a.amount+' ×';b.title='Remove behavior';b.onclick=()=>{remember();selectedObject()?.actions.splice(index,1);renderActions();};$('xr-actions').append(b);}}
$('xr-add-action').onclick=()=>{const o=selectedObject();if(!o)return status('Select an object first.');if(o.actions.length>=100)return;remember();o.actions.push({kind:$('xr-action-kind').value,axis:$('xr-action-axis').value,amount:Math.max(-100,Math.min(100,Number($('xr-action-amount').value)||0))});renderActions();};
function play(){if(playing||!renderer)return;startState=M.clone(current);playing=true;for(const media of mediaElements.values())media.play().catch(e=>status('Media playback unavailable: '+e.message));elapsed=0;transform.detach();selectionBox.visible=false;world=new CANNON.World({gravity:new CANNON.Vec3(...current.environment.gravityVector)});const floor=new CANNON.Body({mass:0,shape:new CANNON.Plane()});floor.quaternion.setFromEuler(-Math.PI/2,0,0);world.addBody(floor);bodies.clear();softBodies.clear();for(const o of current.objects){const mesh=meshes.get(o.id);if(!o.physics)continue;const box=new THREE.Box3().setFromObject(mesh),size=box.getSize(new THREE.Vector3()),center=box.getCenter(new THREE.Vector3());if(current.environment.worldType==='soft-rigid'&&o.type==='sphere'&&o.mass>0&&!(current.joints||[]).some(j=>j.a===o.id||j.b===o.id)){const soft=createSoftSphere(world,{position:center.toArray(),radii:size.toArray().map(v=>Math.max(.03,v/2)),mass:o.mass,bounce:o.bounce});softBodies.set(o.id,soft);continue;}const shape=o.type==='sphere'?new CANNON.Sphere(Math.max(size.x,size.y,size.z)/2):new CANNON.Box(new CANNON.Vec3(Math.max(.02,size.x/2),Math.max(.02,size.y/2),Math.max(.02,size.z/2)));const body=new CANNON.Body({mass:o.mass,shape,material:new CANNON.Material({friction:.4,restitution:o.bounce})});body.position.set(center.x,center.y,center.z);body.quaternion.setFromEuler(...o.rotation.map(THREE.MathUtils.degToRad));world.addBody(body);bodies.set(o.id,{body,offset:center.sub(mesh.position)});}for(const joint of current.joints||[]){const a=bodies.get(joint.a)?.body,b=bodies.get(joint.b)?.body;if(!a||!b)continue;if(joint.type==='fixed')world.addConstraint(new CANNON.LockConstraint(a,b));else{const center=a.position.vadd(b.position).scale(.5),pivotA=center.vsub(a.position),pivotB=center.vsub(b.position);world.addConstraint(new CANNON.HingeConstraint(a,b,{pivotA,pivotB,axisA:new CANNON.Vec3(0,1,0),axisB:new CANNON.Vec3(0,1,0)}));}}$('xr-play').disabled=true;$('xr-stop').disabled=false;renderInspector();renderModeling();status('Simulation running. WASD moves the first car or Player. Stop restores the edit scene.');}
