const importer=document.createElement('input');importer.type='file';importer.accept='.json,.obj';importer.hidden=true;root.append(importer);let importKind='project';importer.onchange=async()=>{try{const file=importer.files[0];if(!file)return;if(file.size>5000000)throw Error('Choose a file smaller than 5 MB.');const source=await file.text();if(importKind==='obj'){if(source.length>3000000||/\b(?:mtllib|map_Kd)\b/i.test(source))throw Error('Use a geometry-only OBJ smaller than 3 MB.');if(!/^v\s/m.test(source)||!/^f\s/m.test(source))throw Error('OBJ must contain vertices and faces.');addObject('obj',{name:file.name.slice(0,120),source});}else{const p=M.validate(JSON.parse(source));p.id=M.id();projects.unshift(p);store();edit(p);}}catch(e){notify('Could not open file',e.message);}finally{importer.value='';}};
