const backgroundInput=document.createElement('input');backgroundInput.type='file';backgroundInput.accept='image/png,image/jpeg,image/webp';backgroundInput.hidden=true;root.append(backgroundInput);$('xr-background-image').onclick=()=>backgroundInput.click();backgroundInput.onchange=async()=>{const f=backgroundInput.files[0];backgroundInput.value='';if(!f)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>5000000)return status('Choose a PNG, JPEG or WebP image under 5 MB.');try{const bitmap=await createImageBitmap(f),canvas=document.createElement('canvas'),scale=Math.min(1,900/Math.max(bitmap.width,bitmap.height));canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const data=canvas.toDataURL('image/jpeg',.85);remember();current.environment.backgroundImage=data;applySceneEnvironment();status('Background image added.');}catch(e){status('Image could not load: '+e.message);}};$('xr-clear-background').onclick=()=>{remember();current.environment.backgroundImage='';applySceneEnvironment();status('Background image removed.');};
