let selectedPart=null;const collapsedNodes=new Set();
function nodeAt(mesh,path){return path.split('/').reduce((node,index)=>node?.children[Number(index)],mesh);}
function prepareHierarchy(mesh,o){const names={bear:['Torso','Head','Left leg','Left arm','Right leg','Right arm','Left ear','Right ear','Left eye','Right eye','Goggles'],robot:['Torso','Head','Left leg','Left arm','Right leg','Right arm','Left eye','Right eye','Visor'],house:['Walls','Roof','Door'],tree:['Trunk','Leaves'],car:['Chassis','Cabin','Left rear wheel','Left front wheel','Right rear wheel','Right front wheel']};const visit=(node,path='')=>{node.children.forEach((child,i)=>{const key=path?path+'/'+i:String(i);child.name=child.name||(!path?names[o.type]?.[i]:null)||(child.isMesh?'Mesh ':child.isLight?'Light ':'Group ')+(i+1);const override=o.parts?.[key];if(override){child.name=override.name;child.visible=override.visible;child.position.fromArray(override.position);child.rotation.set(...override.rotation.map(THREE.MathUtils.degToRad));child.scale.fromArray(override.scale);if(child.isMesh&&override.color){child.material=child.material.clone();child.material.color.set(override.color);}}visit(child,key);});};visit(mesh);}
function partMesh(){return selectedPart&&nodeAt(meshes.get(selectedPart.id),selectedPart.path);}
function partState(mesh){return {name:mesh.name,visible:mesh.visible,position:mesh.position.toArray(),rotation:[mesh.rotation.x,mesh.rotation.y,mesh.rotation.z].map(THREE.MathUtils.radToDeg),scale:mesh.scale.toArray(),...(mesh.isMesh&&mesh.material?.color?{color:'#'+mesh.material.color.getHexString()}: {})};}
function commitPartTransform(){const node=partMesh(),o=selectedObject();if(!node||!o)return;node.scale.clampScalar(.01,100);o.parts||={};o.parts[selectedPart.path]=partState(node);renderPartInspector();status('Part transform changed. Save to keep it.');}
function choosePart(id,path){select(id);selectedPart={id,path};const node=partMesh();if(!node)return;transform.detach();if(!playing)transform.attach(node);selectionBox.setFromObject(node);document.querySelector('.xr-inspector').classList.add('xr-part-visible');renderPartInspector();renderHierarchy();}
function renderPartInspector(){const node=partMesh();if(!node)return;const state=partState(node);$('xr-part-title').textContent=node.name+' · local transform';$('xr-part-name').value=state.name;$('xr-part-visible').checked=state.visible;$('xr-part-color').disabled=!state.color;if(state.color)$('xr-part-color').value=state.color;for(const el of partPanel.querySelectorAll('[data-part-vector]'))el.value=state[el.dataset.partVector][Number(el.dataset.axis)].toFixed(3);$('xr-apply-part').disabled=playing;}
function renderHierarchy(){const tree=$('xr-layers');tree.replaceChildren();tree.setAttribute('role','tree');tree.setAttribute('aria-label','Scene layers');const query=($('xr-layer-search')?.value||'').trim().toLowerCase();
 const row=(parent,{key,name,depth=0,children=[],selectAction,visible,eyeAction,active=false,icon='◇'})=>{const matches=entry=>entry.name.toLowerCase().includes(query)||entry.children?.some(matches);if(query&&!matches({name,children}))return;const wrapper=document.createElement('div');wrapper.setAttribute('role','treeitem');wrapper.setAttribute('aria-level',depth+1);wrapper.setAttribute('aria-selected',String(active));const line=document.createElement('div');line.className='xr-tree-row';line.style.paddingLeft=(6+depth*20)+'px';if(children.length){wrapper.setAttribute('aria-expanded',String(query||!collapsedNodes.has(key)));const toggle=document.createElement('button');toggle.className='xr-tree-toggle';toggle.textContent=collapsedNodes.has(key)&&!query?'▸':'▾';toggle.setAttribute('aria-label',(collapsedNodes.has(key)?'Expand ':'Collapse ')+name);toggle.onclick=()=>{collapsedNodes.has(key)?collapsedNodes.delete(key):collapsedNodes.add(key);renderHierarchy();};line.append(toggle);}else{const spacer=document.createElement('span');spacer.className='xr-tree-toggle';line.append(spacer);}const label=document.createElement('button');label.className='xr-tree-label';label.textContent=icon+'  '+name;label.title=name;label.onclick=selectAction;line.append(label);if(eyeAction){const eye=document.createElement('button');eye.className='xr-tree-eye';eye.textContent=visible?'◉':'○';eye.setAttribute('aria-label',(visible?'Hide ':'Show ')+name);eye.onclick=eyeAction;line.append(eye);}wrapper.append(line);parent.append(wrapper);if(children.length&&(!collapsedNodes.has(key)||query)){const group=document.createElement('div');group.setAttribute('role','group');wrapper.append(group);children.forEach(child=>row(group,{...child,depth:depth+1}));}};
 for(const [name,view]of [['Ground'],['DirectionalLight'],['HemisphereLight'],['Main Camera','main'],['AR Camera','ar']])row(tree,{key:name,name,icon:view?'▣':'◇',selectAction:()=>{if(view){remember();current.environment.editorView=view;applySceneEnvironment(true);syncHistory();}showEditorSettings(true);document.querySelector('.xr-inspector').classList.remove('xr-part-visible');},children:view?[{key:name+'/listener',name:'Audio Listener',icon:'♫',selectAction:openListener}]:[]});
 for(const o of current?.objects||[]){const mesh=meshes.get(o.id);const children=(node,path='')=>(node?.children||[]).map((child,i)=>{const key=path?path+'/'+i:String(i);return {key:o.id+'/'+key,name:child.name||'Part '+(i+1),icon:child.isMesh?'◈':'▣',active:selectedPart?.id===o.id&&selectedPart.path===key,children:children(child,key),selectAction:()=>choosePart(o.id,key),visible:child.visible,eyeAction:()=>{remember();o.parts||={};child.visible=!child.visible;o.parts[key]=partState(child);renderHierarchy();syncHistory();}};});row(tree,{key:o.id,name:o.name,icon:'◈',children:mesh?.children.length?[{key:o.id+'/geometry',name:'geometry',icon:'▣',children:children(mesh),selectAction:()=>select(o.id)}]:[],active:selected===o.id&&!selectedPart,visible:o.visible,selectAction:()=>select(o.id),eyeAction:()=>{remember();o.visible=!o.visible;changed();}});}
 renderJointTree();}
const partPanel=document.createElement('section');partPanel.id='xr-part-inspector';partPanel.innerHTML='<h3 id="xr-part-title">Model part</h3><p>Transforms are relative to the parent model.</p><label>Name <input id="xr-part-name" maxlength="120"></label><label>Visible <input id="xr-part-visible" type="checkbox"></label><label>Color <input id="xr-part-color" type="color"></label>'+['position','rotation','scale'].map(key=>'<label>'+key+'<div class="xr-vector">'+['X','Y','Z'].map((axis,i)=>`<input type="number" step=".1" aria-label="Part ${key} ${axis}" data-part-vector="${key}" data-axis="${i}">`).join('')+'</div></label>').join('')+'<button id="xr-apply-part" class="xr-primary">Apply part properties</button><button id="xr-reset-part">Reset part</button><button id="xr-parent-object">Select parent model</button>';
