$('xr-apply-part').onclick=()=>{const node=partMesh(),o=selectedObject();if(!node||!o||playing)return;const state=partState(node);state.name=$('xr-part-name').value.trim()||state.name;state.visible=$('xr-part-visible').checked;if(state.color)state.color=$('xr-part-color').value;for(const key of ['position','rotation','scale'])state[key]=Array.from(partPanel.querySelectorAll('[data-part-vector="'+key+'"]')).map(el=>Number(el.value));try{M.validatePart(state);}catch(e){return status(e.message);}remember();o.parts||={};o.parts[selectedPart.path]=state;const saved={...selectedPart};rebuild();choosePart(saved.id,saved.path);syncHistory();status('Part properties applied.');};
$('xr-reset-part').onclick=()=>{if(!selectedPart)return;const saved={...selectedPart};remember();delete selectedObject().parts?.[saved.path];rebuild();choosePart(saved.id,saved.path);syncHistory();};$('xr-parent-object').onclick=()=>select(selected);
const listenerPanel=document.createElement('section');listenerPanel.id='xr-listener-inspector';listenerPanel.innerHTML='<h3>Audio Listener</h3><p>Scene playback volume for imported audio and video. Shared between Main and AR cameras.</p><label>Volume <input id="xr-listener-volume" type="range" min="0" max="1" step=".05"></label><label>Muted <input id="xr-listener-muted" type="checkbox"></label><button id="xr-apply-listener" class="xr-primary">Apply audio settings</button>';
