$('xr-toggle-search').onclick=()=>{$('xr-layer-search').hidden=!$('xr-layer-search').hidden;if(!$('xr-layer-search').hidden)$('xr-layer-search').focus();};$('xr-add-layer').onclick=()=>{$('xr-layer-menu').open=false;root.querySelector('[data-panel="library"]').click();};$('xr-expand-layers').onclick=()=>{collapsedNodes.clear();$('xr-layer-menu').open=false;renderHierarchy();};$('xr-collapse-layers').onclick=()=>{for(const o of current.objects){collapsedNodes.add(o.id);collapsedNodes.add(o.id+'/geometry');}collapsedNodes.add('Main Camera');collapsedNodes.add('AR Camera');$('xr-layer-menu').open=false;renderHierarchy();};
