function renderJointTree(){const list=$('xr-joint-tree-items');if(!list)return;list.replaceChildren();if(!current?.joints.length){list.textContent='No physics joints. Use + to connect two bodies.';return;}current.joints.forEach((j,i)=>{const row=document.createElement('div');const b=document.createElement('button');b.textContent=j.type+' · '+current.objects.find(o=>o.id===j.a)?.name+' ↔ '+current.objects.find(o=>o.id===j.b)?.name;b.onclick=()=>{select(j.a);root.querySelector('[data-panel="modeling"]').click();$('xr-model-target').value=j.b;};const remove=document.createElement('button');remove.textContent='×';remove.setAttribute('aria-label','Remove joint '+(i+1));remove.onclick=()=>{remember();current.joints.splice(i,1);renderModeling();renderJointTree();syncHistory();};row.append(b,remove);list.append(row);});}

